+    with_retract.push(PathMove {
+        kind: MoveKind::Feed,
+        from_tip: [10.0, 0.0, 50.0],
+        to_tip: [10.0, 0.0, 0.0],
+        from_axis: axis_from_deg(40.0, 350.0),
+        to_axis: axis_from_deg(40.0, 390.0),
+        feed: Some(500.0),
