+    let err = solve_path(&cfg, &with_retract, &opts)
+        .expect_err("unchecked clearance unwind must not be synthesized");
+    assert!(
+        err.to_string().contains("C") && err.to_string().contains("450"),
+        "refusal should name C and travel: {err}"
+    );
